<?php require __DIR__.'/../../bootstrap/app.php';role_required('admin');$db=Database::get();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$a=$_POST['action']??'';
 if($a==='approve'){$s=$db->prepare("SELECT * FROM technician_applications WHERE id=? AND status<>'approved'");$s->execute([$id]);$ap=$s->fetch();
  if($ap){$pw=temp_password();try{$db->beginTransaction();$db->prepare("INSERT INTO users(name,email,phone,password_hash,role_id,status) VALUES(?,?,?,?,(SELECT id FROM roles WHERE name='technical'),'active')")->execute([$ap['full_name'],$ap['email'],$ap['phone'],password_hash($pw,PASSWORD_DEFAULT)]);$uid=(int)$db->lastInsertId();
   $db->prepare("INSERT INTO technician_profiles(user_id,specialization,experience_years,verification_status) VALUES(?,?,?,'verified')")->execute([$uid,$ap['specialization'],$ap['experience_years']]);$db->prepare("UPDATE technician_applications SET status='approved' WHERE id=?")->execute([$id]);$db->commit();audit('approve technician','technician_application',$id);
   notice('Approved. Account created for '.$ap['email'].'. Temporary password (shown once, give it to the technician): '.$pw);}catch(PDOException $x){if($db->inTransaction())$db->rollBack();notice($x->getCode()==='23000'?'An account with this email already exists. Use the Users page to change its role.':'Could not approve this application.');}}}
 elseif(in_array($a,['under_review','shortlisted','rejected'],true)){$db->prepare("UPDATE technician_applications SET status=? WHERE id=?")->execute([$a,$id]);audit('application '.$a,'technician_application',$id);notice('Application updated.');}
 go('admin/applications.php');}
$rows=$db->query("SELECT * FROM technician_applications ORDER BY (status='submitted') DESC,id DESC LIMIT 100")->fetchAll();
$jobs=$db->query("SELECT full_name,email,phone,status FROM job_applications ORDER BY id DESC LIMIT 50")->fetchAll();
$title='Applications';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Technician applications</h1>
<?php if(!$rows):?><p>No applications yet.</p><?php endif;?><?php foreach($rows as $r):?><div class="cardx mb-3"><b><?=e($r['full_name'])?></b> · <?=e($r['email'])?> · <?=e($r['phone'])?> · <span class="badge bg-secondary"><?=e($r['status'])?></span><p class="mb-1 mt-2"><?=e($r['specialization'])?> · <?=(int)$r['experience_years']?> years</p><p><?=nl2br(e($r['skills']))?></p>
<?php if($r['status']!=='approved'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="action" value="approve" class="btn btn-sm btn-success">Approve and create account</button> <button name="action" value="under_review" class="btn btn-sm btn-outline-dark">Under review</button> <button name="action" value="shortlisted" class="btn btn-sm btn-outline-dark">Shortlist</button> <button name="action" value="rejected" class="btn btn-sm btn-outline-danger">Reject</button></form><?php endif;?></div><?php endforeach;?>
<h2 class="mt-4">Job applications</h2><?php if(!$jobs):?><p>None yet.</p><?php else:?><table class="table"><tr><th>Name</th><th>Email</th><th>Phone</th><th>Status</th></tr><?php foreach($jobs as $j):?><tr><td><?=e($j['full_name'])?></td><td><?=e($j['email'])?></td><td><?=e($j['phone'])?></td><td><?=e($j['status'])?></td></tr><?php endforeach;?></table><?php endif;?></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>
